layout_css:
.worksheet-wrapper {
  max-width: 820px;
  margin: 0 auto;
}
.worksheet-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
  padding: 12px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.06);
  border: 1px solid rgba(148, 163, 184, 0.3);
}
.worksheet-toolbar button {
  padding: 8px 14px;
  border-radius: 6px;
  border: 1px solid #475569;
  background: #ffffff;
  color: #0f172a;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
}
.worksheet-toolbar button.is-active {
  background: #1e293b;
  color: #ffffff;
}
.worksheet-header-box {
  border: 2px solid currentColor;
  padding: 16px;
  margin-bottom: 20px;
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 12px;
  align-items: center;
}
.worksheet-name-box {
  border-bottom: 1px solid currentColor;
  padding: 6px 0;
  font-size: 14px;
}
.worksheet-q-card {
  border-bottom: 1px solid rgba(148, 163, 184, 0.4);
  padding: 16px 0;
}
.worksheet-answer-sheet-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 16px;
}
.worksheet-answer-sheet-table th,
.worksheet-answer-sheet-table td {
  border: 2px solid currentColor;
  padding: 12px;
  text-align: left;
}
.worksheet-answer-text {
  color: #dc2626;
  font-weight: 800;
}
@media print {
  .worksheet-toolbar { display: none !important; }
  .worksheet-wrapper { box-shadow: none !important; border: none !important; }
}
